"""Static, reviewable derivation of additive adapters; never rewrite old inputs.
Run --check to verify exact reproduction. No runtime SQL rewriting or bypass flag.
"""
import hashlib,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
files={'v12':'migrations-d3-proposed/V12__planning_snapshot_and_publication.sql','v13':'migrations-d3-dispatch-proposed/V13__guarded_dispatch.sql','v16':'migrations-d4-proposed/V16__durable_worker_delivery.sql','v17':'migrations-d4-proposed/V17__worker_transport_commands.sql'}
def fn(file,name):
 text=(ROOT/files[file]).read_text();start=text.index('CREATE FUNCTION '+name+'(');end=text.index('END $$;',start)+len('END $$;');return text[start:end]
def replace_once(s,old,new):
 assert s.count(old)==1,(old,s.count(old));return s.replace(old,new)
parts=['-- SPDX-License-Identifier: GPL-3.0-only\n-- GENERATED by testing/D4/generate-continuation-admission.py.\n-- Additive copies preserve every admission check except the explicitly replaced\n-- absence-only predicate, now also allowing a sealed authorized checkpoint.\n']
for file in ['v12','v13','v16','v17']:parts.append('-- Source SHA256 '+files[file]+': '+hashlib.sha256((ROOT/files[file]).read_bytes()).hexdigest()+'\n')
s=fn('v12','d3.observe_eligibility');s=replace_once(s,'CREATE FUNCTION d3.observe_eligibility','CREATE FUNCTION d4.observe_continuation_eligibility')
start=s.index('      AND (NOT EXISTS(SELECT 1 FROM public.execution_attempts');end=s.index('\n',start)
clause=s[start:end]
# Last ')' closes the whole no-attempt/absence disjunction. Append inside it.
s=replace_once(s,clause,clause[:-1]+' OR d4.continuation_safe(item.id,item.lease_generation))')
parts.append(s+'\n')
for file,name,newname in [('v12','d3.publish','d4.publish_continuation'),('v13','d3.dispatch','d4.dispatch_continuation')]:
 s=fn(file,name);s=replace_once(s,'CREATE FUNCTION '+name,'CREATE FUNCTION '+newname)
 if name=='d3.publish':
  old="AND status<>'ABSENT')) THEN";new="AND status<>'ABSENT')) AND NOT d4.continuation_safe(op.id,op.lease_generation) THEN"
 else:
  old="AND status<>'ABSENT')) THEN";new="AND status<>'ABSENT')) AND NOT d4.continuation_safe(oid,op.lease_generation) THEN"
 s=replace_once(s,old,new)
 if name=='d3.dispatch':
  # Recheck checkpoint admission/readset at CLAIM, then bind one child atomically.
  needle='  at_time=clock_timestamp();'
  s=replace_once(s,needle,"  IF EXISTS(SELECT 1 FROM d4.continuation_admissions WHERE operation_id=oid AND eligible) AND\n    (body->'d4.continuation_admissions' IS DISTINCT FROM c.body->'d4.continuation_admissions' OR body->'d4.checkpoint_proofs' IS DISTINCT FROM c.body->'d4.checkpoint_proofs') THEN\n    RAISE EXCEPTION 'Checkpoint admission changed since capture' USING ERRCODE='40001';END IF;\n"+needle)
  needle='  result=result||jsonb_build_object(\'plan_id\',pid,\'operation_id\',oid);'
  s=replace_once(s,needle,"  INSERT INTO d4.continuation_links(checkpoint_id,authorization_id,attempt_id,generation)\n    SELECT cp.id,au.id,(result->>'attempt_id')::uuid,(result->>'generation')::bigint FROM d4.checkpoints cp\n    JOIN d4.continuation_authorizations au ON au.checkpoint_id=cp.id WHERE cp.operation_id=oid AND cp.source_generation=op.lease_generation;\n"+needle)
 parts.append(s+'\n')
s=fn('v16','d4.deliver');s=replace_once(s,'CREATE FUNCTION d4.deliver','CREATE FUNCTION d4.deliver_continuation');s=replace_once(s,'result=d3.dispatch(','result=d4.dispatch_continuation(');parts.append(s+'\n')
s=fn('v17','d4.transport');s=replace_once(s,'CREATE FUNCTION d4.transport','CREATE FUNCTION d4.transport_continuation');s=replace_once(s,'assignment=d4.deliver(','assignment=d4.deliver_continuation(');parts.append(s+'\n')
parts.append('REVOKE ALL ON FUNCTION d4.observe_continuation_eligibility(uuid),d4.publish_continuation(uuid,jsonb),d4.dispatch_continuation(uuid,jsonb),d4.deliver_continuation(uuid,uuid,jsonb),d4.transport_continuation(uuid,uuid,jsonb) FROM PUBLIC;\n')
target=ROOT/'migrations-d4-proposed/V20__continuation_admission_adapters.sql';out='\n'.join(parts)
if '--check' in sys.argv:assert target.read_text()==out,'Generated admission adapters differ'
else:target.write_text(out)
# Preserve the closed D3 Java source; its new adapter admits a captured typed seal.
p=ROOT/'scheduler-postgres/src/main/java/io/github/isidorotrevino/planner/postgres/PlanningStore.java';s=p.read_text().replace('PlanningStore','ContinuationPlanningStore')
s=s.replace('/** JDBC boundary.', '/** D4 continuation adapter (d4.continuation.snapshot.v1). Derived from closed D3, SHA256 '+hashlib.sha256(p.read_bytes()).hexdigest()+'.\n * JDBC boundary.')
s=s.replace('SELECT d3.observe_eligibility(?)','SELECT d4.observe_continuation_eligibility(?)')
s=s.replace('"SELECT d3."+fn+','"SELECT "+(fn.equals("publish")?"d4.":"d3.")+(fn.equals("publish")?"publish_continuation":fn)+')
needle="er->>'status'<>'ABSENT') retry_safe,"
s=replace_once(s,needle,"er->>'status'<>'ABSENT') OR EXISTS(SELECT 1 FROM jsonb_array_elements(b->'d4.continuation_admissions') cp WHERE cp->>'operation_id'=o->>'id' AND cp->>'generation'=o->>'lease_generation' AND cp->>'admission_kind'='SEALED_CHECKPOINT' AND cp->'eligible'='true'::jsonb) retry_safe,")
p=ROOT/'testing/D4/lab/src/main/java/io/github/isidorotrevino/planner/postgres/ContinuationPlanningStore.java'
if '--check' in sys.argv:assert p.read_text()==s,'Generated continuation Java differs'
else:p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
